// 🔴 event logic in an Effect
useEffect(() => {
  if (product.isInCart) {
    showNotification("Added!");
  }
}, [product]);

// ✅ shared function, called from handlers
function buyProduct() {
  addToCart(product);
  showNotification("Added!");
}
function handleBuyClick() {
  buyProduct();
}
